  $j${"child": "not written; nothing to revert", "engine": "ask652/w4/write/revert_eng_651_652.json, md5 60a8ddf02c11f8b0cf506816b2a71f75 (restores 7f4e5503; md5 from W4's facts file); one file reverts ASK 651 and ASK 652 together", "source": "Wall 12127; W4's facts file", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read"}$j$::jsonb,
  $j$[{"seat": "W1", "source": "Wall 12101", "verdict": "FAIL F1 (plan rev 0)", "wall_id": 12101, "md5_graded": "bce5be7f", "verdict_norm": "FAIL"}, {"seat": "W1", "source": "Wall 12103", "verdict": "PASS (plan rev 1)", "wall_id": 12103, "md5_graded": "c82c1d69", "verdict_norm": "PASS"}, {"seat": "W1", "source": "Wall 12108", "verdict": "PASS (build b1, ASK 651 and 652 together)", "wall_id": 12108, "md5_graded": "1aa15175", "verdict_norm": "PASS"}, {"seat": "W1", "source": "Wall 12152, item 3", "verdict": "PASS (written target check with the full md5, made after the write: equal to live 50ade174, 426 nodes, 0 differences, connections equal)", "wall_id": 12152, "md5_graded": "1aa1517517fc227ef4e8d9cd75d05917", "verdict_norm": "PASS"}]$j$::jsonb,
