  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, nodes D4 Build, Panel Build, Build Independent Verdict and Shared Library (LIB line 36)", "after": "version 50ade174-e08d-48a2-95de-1fd4bcbebcfd, 426 nodes; refCheck reads to the end of the line (four copies, tagged ASK 651); the premise reader passes over a reference that is neither a pressed verse nor a press past the cap of PRS.premise (three copies, tagged ASK 652); 29 MAP lengths re-measured; LIB 78f56d1449dc8e96, map b5974b30d48fe432", "before": "version 7f4e5503; PRS refCheck reads 160 characters after a reference; the premise reader in D4 Build, Panel Build and Build Independent Verdict treats every reference in a PRESSED WITH block as a press"}]$j$::jsonb,
  $j$[{"name": "t651_652.cjs on the build", "result": "ALL PASS (28): each of the four refCheck copies gives Luke 1:35 PROVEN BY REFERENCE on 42528 DR1; no PROVEN BY REFERENCE verdict of 42528 or 42373 changes; a quotation with no closing mark on its line still fails; a verse named but not quoted still reads \"not quoted\"; the LIB source writes the newline escaped (test 6); 10 real presses give 8 counted and \"over the cap\" names the two past it, not an [L3] verse (test 28); the PRSP-null case", "source": "Wall 12105; run by W1 on its own rebuild, Wall 12108, and on live, Wall 12129"}, {"name": "Judge ledger replay, 42528 and 42373, before and after", "result": "42528: Luke 1:35 becomes PROVEN BY REFERENCE in defender premises 2, 3 and 4; 25 layer verses of the Oracle's presses lose the label \"UNPROVEN, not a witness\"; Job 14:1 and Acts 13:33 are counted as presses; both WALL-2024 floor items stay (Luke 1:34 in premise 4, 2 Samuel 7:12). 42373: the challenger's presses Luke 1:32 and Hebrews 7:10 are counted. Panel Build and Build Independent Verdict give the same text.", "source": "Wall 12105; the 42528 ledger read by W1, Wall 12108"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W4, W1), before and after the write (W4, Wall 12127) and on live (W1, Wall 12129); pair Library Check PASSES; one-copy check PASS", "source": "Wall 12105, 12108, 12127, 12129"}, {"name": "NOT RUN", "result": "any live call", "source": "Wall 12127"}]$j$::jsonb,
